-- Seed the complete, reviewed Brains Heist diagnostic taxonomy for the 720
-- immutable verified questions audited on 2026-08-24.
--
-- This migration resolves only the current verified question, current active
-- assessment item, and the exact approved primary objective mapping for the
-- manifest's framework/scope/objective. It intentionally does not retrofit
-- historical assignment_questions snapshots or completed evidence.

create temporary table _bh_verified_question_taxonomy_manifest
on commit drop
as
select
  payload,
  trim(payload->>'externalId') as external_id,
  trim(payload->>'scopeCode') as scope_code,
  trim(payload->>'objectiveCode') as objective_code,
  trim(payload->>'packageId') as package_id,
  trim(payload->>'packageVersion') as package_version,
  trim(payload->>'contentVersion') as content_version,
  trim(payload->>'frameworkCode') as framework_code,
  trim(payload->>'frameworkVersionCode') as framework_version_code,
  trim(payload->>'primarySkillCode') as primary_skill_code,
  trim(payload->>'primarySkillName') as primary_skill_name,
  trim(payload->>'atomicSubskillCode') as atomic_subskill_code,
  trim(payload->>'atomicSubskillName') as atomic_subskill_name,
  trim(payload->>'assessmentProcessCode') as assessment_process_code,
  trim(payload->>'cognitiveProcess') as cognitive_process,
  trim(payload->>'evidenceStatement') as evidence_statement,
  coalesce(
    array(
      select jsonb_array_elements_text(
        coalesce(payload->'secondarySkillCodes', '[]'::jsonb)
      )
    ),
    '{}'::text[]
  ) as secondary_skill_codes,
  (payload->>'confidence')::numeric(4,3) as confidence_score,
  trim(payload->>'reviewStatus') as review_status,
  (payload->>'humanReview')::boolean as human_review_required,
  nullif(trim(payload->>'reviewReason'), '') as review_reason,
  trim(payload->>'taxonomyVersion') as taxonomy_version
from jsonb_array_elements(
  $bh_verified_question_taxonomy$
