do $manifest_validation$
declare
  v_manifest_count integer;
  v_distinct_external_ids integer;
begin
  select count(*), count(distinct external_id)
  into v_manifest_count, v_distinct_external_ids
  from _bh_verified_question_taxonomy_manifest;

  if v_manifest_count <> 720 then
    raise exception using errcode = '23514',
      message = 'verified_question_taxonomy_manifest_must_contain_720_rows';
  end if;
  if v_distinct_external_ids <> 720 then
    raise exception using errcode = '23505',
      message = 'verified_question_taxonomy_manifest_external_ids_must_be_unique';
  end if;
  if exists (
    select 1
    from _bh_verified_question_taxonomy_manifest manifest
    where jsonb_typeof(manifest.payload) <> 'object'
       or manifest.external_id = ''
       or manifest.scope_code = ''
       or manifest.objective_code = ''
       or manifest.package_id = ''
       or manifest.package_version = ''
       or manifest.content_version = ''
       or manifest.framework_code = ''
       or manifest.framework_version_code = ''
       or manifest.primary_skill_code = ''
       or manifest.atomic_subskill_code = ''
       or manifest.assessment_process_code not in ('AO1', 'AO2', 'AO3', 'AO4')
       or not (
         (manifest.assessment_process_code = 'AO1'
           and manifest.cognitive_process in ('remember', 'understand'))
         or (manifest.assessment_process_code = 'AO2'
           and manifest.cognitive_process = 'apply')
         or (manifest.assessment_process_code = 'AO3'
           and manifest.cognitive_process = 'analyze')
         or (manifest.assessment_process_code = 'AO4'
           and manifest.cognitive_process = 'evaluate')
       )
       or manifest.taxonomy_version <> 'bh-canonical-1'
       or manifest.review_status <> 'approved'
       or manifest.human_review_required
       or manifest.confidence_score < 0.900
       or manifest.primary_skill_code
         !~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*([.][a-z0-9]+(-[a-z0-9]+)*)+$'
       or manifest.atomic_subskill_code
         !~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*([.][a-z0-9]+(-[a-z0-9]+)*)+$'
       or manifest.atomic_subskill_code
         not like manifest.primary_skill_code || '.%'
  ) then
    raise exception using errcode = '23514',
      message = 'verified_question_taxonomy_manifest_contains_invalid_or_unapproved_row';
  end if;
end;
$manifest_validation$;

create unique index _bh_verified_question_taxonomy_manifest_external_id_uidx
  on _bh_verified_question_taxonomy_manifest(external_id);

create temporary table _bh_verified_question_taxonomy_resolved
on commit drop
as
select
  manifest.*,
  question.id as question_id,
  question.verified_content_hash as question_content_hash,
  assessment_item.id as assessment_item_id,
  curriculum_mapping.id as curriculum_mapping_id
from _bh_verified_question_taxonomy_manifest manifest
join public.questions question
  on question.verified_external_id = manifest.external_id
 and question.content_origin = 'brain_heist'
 and question.verification_status = 'verified'
 and question.analytics_eligible
 and question.is_public
 and question.is_active
 and question.current_content_hash = question.verified_content_hash
 and question.content_version = manifest.content_version
join public.curriculum_assessment_items assessment_item
  on assessment_item.source_type = 'question_bank'
 and assessment_item.source_record_id = question.id::text
 and assessment_item.source_item_key = 'question'
 and assessment_item.is_active
 and assessment_item.retired_at is null
 and assessment_item.academic_subject_id = question.academic_subject_id
 and assessment_item.content_hash = question.verified_content_hash
 and assessment_item.source_version = manifest.content_version
 and assessment_item.source_metadata->>'verifiedExternalId' = manifest.external_id
 and assessment_item.source_metadata->>'packageId' = manifest.package_id
 and assessment_item.source_metadata->>'packageVersion' = manifest.package_version
join public.curriculum_item_objective_mappings curriculum_mapping
  on curriculum_mapping.assessment_item_id = assessment_item.id
 and curriculum_mapping.academic_subject_id = assessment_item.academic_subject_id
 and curriculum_mapping.status = 'approved'
 and curriculum_mapping.mapping_role = 'primary'
 and curriculum_mapping.superseded_at is null
 and curriculum_mapping.item_content_hash = assessment_item.content_hash
join public.curriculum_framework_versions framework_version
  on framework_version.id = curriculum_mapping.framework_version_id
 and framework_version.version_code = manifest.framework_version_code
 and framework_version.status in ('published', 'retired')
 and framework_version.content_hash =
   curriculum_mapping.curriculum_version_content_hash
join public.curriculum_frameworks framework
  on framework.id = framework_version.framework_id
 and framework.code = manifest.framework_code
 and framework.is_active
join public.curriculum_scopes scope
  on scope.id = curriculum_mapping.curriculum_scope_id
 and scope.framework_version_id = framework_version.id
 and scope.academic_subject_id = assessment_item.academic_subject_id
 and scope.code = manifest.scope_code
join public.curriculum_objectives objective
  on objective.id = curriculum_mapping.curriculum_objective_id
 and objective.framework_version_id = framework_version.id
 and objective.curriculum_scope_id = scope.id
 and objective.code = manifest.objective_code
 and objective.is_assessable;

create unique index _bh_verified_question_taxonomy_resolved_external_id_uidx
  on _bh_verified_question_taxonomy_resolved(external_id);

do $resolution_validation$
declare
  v_resolved_count integer;
  v_question_count integer;
  v_item_count integer;
  v_mapping_count integer;
begin
  select
    count(*),
    count(distinct question_id),
    count(distinct assessment_item_id),
    count(distinct curriculum_mapping_id)
  into
    v_resolved_count,
    v_question_count,
    v_item_count,
    v_mapping_count
  from _bh_verified_question_taxonomy_resolved;

  if v_resolved_count <> 720
     or v_question_count <> 720
     or v_item_count <> 720
     or v_mapping_count <> 720 then
    raise exception using errcode = '23514',
      message = 'verified_question_taxonomy_must_resolve_exactly_720_current_items_and_mappings',
      detail = format(
        'resolved=%s questions=%s items=%s mappings=%s',
        v_resolved_count, v_question_count, v_item_count, v_mapping_count
      );
  end if;
  if exists (
    select 1
    from _bh_verified_question_taxonomy_manifest manifest
    left join _bh_verified_question_taxonomy_resolved resolved
      on resolved.external_id = manifest.external_id
    where resolved.external_id is null
  ) then
    raise exception using errcode = '23514',
      message = 'verified_question_taxonomy_contains_orphan_or_mapping_mismatch';
  end if;
end;
$resolution_validation$;

insert into public.verified_question_diagnostic_taxonomy (
  question_id,
  assessment_item_id,
  curriculum_mapping_id,
  question_content_hash,
  scope_code,
  objective_code,
  package_version,
  taxonomy_version,
  primary_skill_code,
  primary_skill_name,
  atomic_subskill_code,
  atomic_subskill_name,
  assessment_process_code,
  cognitive_process,
  evidence_statement,
  secondary_skill_codes,
  confidence_score,
  review_status,
  human_review_required,
  review_reason,
  reviewed_by_authority,
  reviewed_at,
  taxonomy_hash
)
select
  resolved.question_id,
  resolved.assessment_item_id,
  resolved.curriculum_mapping_id,
  resolved.question_content_hash,
  resolved.scope_code,
  resolved.objective_code,
  resolved.package_version,
  resolved.taxonomy_version,
  resolved.primary_skill_code,
  resolved.primary_skill_name,
  resolved.atomic_subskill_code,
  resolved.atomic_subskill_name,
  resolved.assessment_process_code,
  resolved.cognitive_process,
  resolved.evidence_statement,
  resolved.secondary_skill_codes,
  resolved.confidence_score,
  resolved.review_status,
  resolved.human_review_required,
  resolved.review_reason,
  'Brains Heist Academic Taxonomy Audit 2026-08-24',
  now(),
  ''
from _bh_verified_question_taxonomy_resolved resolved
on conflict do nothing;

do $coverage_validation$
declare
  v_exact_coverage integer;
  v_taxonomy_version_total integer;
begin
  select count(*)
  into v_exact_coverage
  from _bh_verified_question_taxonomy_resolved resolved
  join public.verified_question_diagnostic_taxonomy taxonomy
    on taxonomy.question_id = resolved.question_id
   and taxonomy.assessment_item_id = resolved.assessment_item_id
   and taxonomy.curriculum_mapping_id = resolved.curriculum_mapping_id
   and taxonomy.question_content_hash = resolved.question_content_hash
   and taxonomy.scope_code = resolved.scope_code
   and taxonomy.objective_code = resolved.objective_code
   and taxonomy.package_version = resolved.package_version
   and taxonomy.taxonomy_version = resolved.taxonomy_version
   and taxonomy.primary_skill_code = resolved.primary_skill_code
   and taxonomy.primary_skill_name = resolved.primary_skill_name
   and taxonomy.atomic_subskill_code = resolved.atomic_subskill_code
   and taxonomy.atomic_subskill_name = resolved.atomic_subskill_name
   and taxonomy.assessment_process_code = resolved.assessment_process_code
   and taxonomy.cognitive_process = resolved.cognitive_process
   and taxonomy.evidence_statement = resolved.evidence_statement
   and taxonomy.secondary_skill_codes = resolved.secondary_skill_codes
   and taxonomy.confidence_score = resolved.confidence_score
   and taxonomy.review_status = 'approved'
   and not taxonomy.human_review_required
   and taxonomy.review_reason is not distinct from resolved.review_reason
   and taxonomy.reviewed_by_authority =
     'Brains Heist Academic Taxonomy Audit 2026-08-24'
   and taxonomy.taxonomy_hash ~ '^[0-9a-f]{64}$';

  select count(*)
  into v_taxonomy_version_total
  from public.verified_question_diagnostic_taxonomy taxonomy
  where taxonomy.taxonomy_version = 'bh-canonical-1';

  if v_exact_coverage <> 720 then
    raise exception using errcode = '23514',
      message = 'verified_question_taxonomy_current_version_coverage_must_equal_720',
      detail = format('exact_coverage=%s', v_exact_coverage);
  end if;
  if v_taxonomy_version_total <> 720 then
    raise exception using errcode = '23514',
      message = 'verified_question_taxonomy_current_version_contains_orphan_or_mismatch',
      detail = format('taxonomy_version_total=%s', v_taxonomy_version_total);
  end if;
  if exists (
    select 1
    from public.verified_question_diagnostic_taxonomy taxonomy
    left join _bh_verified_question_taxonomy_resolved resolved
      on resolved.question_id = taxonomy.question_id
     and resolved.taxonomy_version = taxonomy.taxonomy_version
    where taxonomy.taxonomy_version = 'bh-canonical-1'
      and resolved.question_id is null
  ) then
    raise exception using errcode = '23514',
      message = 'verified_question_taxonomy_current_version_orphan_detected';
  end if;
end;
$coverage_validation$;
